\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{booktabs}
\pagestyle{empty}

% ── Lancet Clinical Palette: Deep Navy + Clinical Teal ──
\definecolor{primary}{HTML}{0B2545}      % deep navy
\definecolor{secondary}{HTML}{0E6B8A}    % clinical teal
\definecolor{accent}{HTML}{C8913A}       % muted gold
\definecolor{bgposter}{HTML}{F0F4F8}     % cool blue-grey background
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E6F4F8}
\definecolor{statgold}{HTML}{FDF3E3}

% Card tinted backgrounds
\definecolor{navybg}{HTML}{EBF0F5}
\definecolor{tealbg}{HTML}{E8F4F8}
\definecolor{goldbg}{HTML}{FBF5EA}
\definecolor{navytitlebg}{HTML}{D8E3EE}
\definecolor{tealtitlebg}{HTML}{CCE9F0}
\definecolor{goldtitlebg}{HTML}{F5E8D2}

\pagecolor{bgposter}
\color{textdark}

\setlist[itemize]{leftmargin=22pt, itemsep=7pt, parsep=1pt, topsep=3pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=7pt, parsep=1pt, topsep=3pt,
  label={\color{primary}\bfseries\arabic*.}}

\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navybg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=navytitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=goldtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=16pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.28}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries\color{white}
    Artificial Intelligence in Clinical Decision-Making}\\[10pt]
  {\fontsize{38}{46}\selectfont\color{white}
    Performance, Safety, and Implementation Gaps}\\[10pt]
  {\fontsize{28}{36}\selectfont\color{white!75}
    Evidence Synthesis \textbullet\ 400+ Studies \textbullet\
    \textit{The Lancet Digital Health} AI in Clinical Medicine Symposium}
}

%% ══════════════════════════════════════════════
%% STAT BANNER
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{secondary!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} 87.5\%}\\[3pt]
      {\fontsize{23}{28}\selectfont\color{secondary}\bfseries AI Sensitivity}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textgray} vs.\ 78.2\% clinician-only}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{accent!60}{statgold}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{accent} {<}5\%}\\[3pt]
      {\fontsize{23}{28}\selectfont\color{accent}\bfseries Prospective Validation}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textgray} of published AI models}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{primary!40}{navybg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} 18\%}\\[3pt]
      {\fontsize{23}{28}\selectfont\color{primary}\bfseries Bias Assessment}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textgray} studies reporting equity data}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{secondary!50}{tealbg}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{secondary} 32\%}\\[3pt]
      {\fontsize{23}{28}\selectfont\color{secondary}\bfseries Faster Diagnosis}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textgray} turnaround time reduction}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{accent!50}{statgold}{\parbox{0.90\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{accent} 692}\\[3pt]
      {\fontsize{23}{28}\selectfont\color{accent}\bfseries FDA-Cleared}\\[2pt]
      {\fontsize{20}{24}\selectfont\color{textgray} AI/ML medical devices}\vspace{5pt}%
    }}
  \end{minipage}
}

%% ══════════════════════════════════════════════
%% COL 1 ROW A: Background & Motivation
%% ══════════════════════════════════════════════
\posterbox[navycard, title={Background \& Motivation}
]{name=background, column=1, between=row7 and row11}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}
    \item AI-based clinical decision support systems (CDSS) are advancing rapidly across diagnostic, prognostic, and therapeutic domains
    \item Deep learning architectures show consistent gains in medical imaging interpretation over individual clinicians
    \item Translation from research to bedside practice remains critically limited despite published evidence
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont\color{primary}
    \textbf{Core question:} Does AI performance in controlled trials translate to real-world clinical benefit?
  }}
}

%% ══════════════════════════════════════════════
%% COL 1 ROW B: Safety, Bias & Health Equity
%% ══════════════════════════════════════════════
\posterbox[tealcard, title={Safety, Bias \& Health Equity}
]{name=safety, column=1, between=row11 and row16}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}
    \item Only \textbf{18\%} of studies reported any demographic bias assessment (age, sex, ethnicity, SES)
    \item Sensitivity disparities of \textbf{5--12 percentage points} documented in underrepresented groups
    \item Dermatology AI trained predominantly on lighter skin tones shows worst equity gaps
    \item Adverse AI-attributable events in ${<}1\%$ of prospective trials --- but under-reporting suspected
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!22}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont\color{accent!80!black}
    $\Rightarrow$ \textbf{No standardised safety-reporting framework} exists for AI-CDSS
  }}
}

%% ══════════════════════════════════════════════
%% COL 1 ROW C: References
%% ══════════════════════════════════════════════
\posterbox[navycard, title={Key References}
]{name=references, column=1, between=row16 and bottom}{
  \fontsize{26}{36}\selectfont\color{textgray}
  \begin{enumerate}[leftmargin=20pt, itemsep=5pt]
    \item Topol E. (2019). High-performance medicine: human \& AI. \textit{Nat Med}.
    \item Rajpurkar P et al. (2022). AI in health and medicine. \textit{Nat Med}.
    \item Obermeyer Z et al. (2019). Dissecting racial bias in algorithms. \textit{Science}.
    \item FDA (2023). Artificial Intelligence/Machine Learning action plan.
    \item Kelly C et al. (2019). Key challenges for delivering clinical impact with AI. \textit{Lancet Digit Health}.
  \end{enumerate}
}

%% ══════════════════════════════════════════════
%% COL 2 ROW A: Diagnostic Performance
%% ══════════════════════════════════════════════
\posterbox[tealcard, title={Diagnostic Performance}
]{name=performance, column=2, between=row7 and row13}{
  \fontsize{30}{40}\selectfont

  {\fontsize{31}{40}\selectfont\bfseries\color{secondary} Sensitivity Comparison (median across 400+ studies)}
  \vspace{6pt}

  \renewcommand{\arraystretch}{1.55}
  \fontsize{27}{34}\selectfont
  \begin{tabular}{lcccc}
    \toprule
    \rowcolor{secondary!15}
    \textbf{Domain} & \textbf{AI Sens.} & \textbf{Clin. Sens.} & \textbf{AI Spec.} & \textbf{Clin. Spec.} \\
    \midrule
    Radiology    & 89.3\% & 79.8\% & 94.0\% & 92.1\% \\
    \rowcolor{tealbg}
    Dermatology  & 86.7\% & 76.5\% & 91.8\% & 89.4\% \\
    Ophthalmology & 90.1\% & 82.3\% & 95.2\% & 93.7\% \\
    \rowcolor{tealbg}
    Pathology    & 84.0\% & 74.1\% & 91.5\% & 90.0\% \\
    \midrule
    \rowcolor{secondary!20}
    \textbf{Median} & \textbf{87.5\%} & \textbf{78.2\%} & \textbf{93.1\%} & \textbf{91.4\%} \\
    \bottomrule
  \end{tabular}

  \vspace{10pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont\color{secondary!80!black}
    $\Rightarrow$ \textbf{+9.3 pp sensitivity gain} with AI across imaging domains; largest in ophthalmology (+7.8 pp)
  }}

  \vspace{6pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont\color{primary}
    $\Rightarrow$ \textbf{32\% reduction} in diagnostic turnaround time --- critical for emergency \& time-sensitive care
  }}
}

%% ══════════════════════════════════════════════
%% COL 2 ROW B: The Implementation Gap
%% ══════════════════════════════════════════════
\posterbox[goldcard, title={The Translational Implementation Gap}
]{name=gap, column=2, between=row13 and row18}{
  \fontsize{30}{40}\selectfont

  \colorbox{accent!25}{\parbox{0.94\linewidth}{%
    \fontsize{34}{44}\selectfont\bfseries\color{accent!80!black}
    692 FDA-cleared AI devices --- yet \textbf{{<}5\% of published models} ever reach prospective validation
  }}

  \vspace{8pt}
  {\fontsize{31}{40}\selectfont\bfseries\color{accent} Key Barriers to Clinical Deployment:}
  \vspace{4pt}
  \begin{itemize}
    \item \textbf{Data fragmentation:} EHR interoperability \& open-standards gaps (FHIR, OMOP)
    \item \textbf{Regulatory lag:} Evolving FDA/CE frameworks behind AI development pace
    \item \textbf{Clinician trust:} Insufficient explainability \& model transparency
    \item \textbf{Economic evidence:} Scarce cost-effectiveness data for health-system investment
    \item \textbf{Workflow mismatch:} Poor integration with existing clinical processes
  \end{itemize}
}

%% ══════════════════════════════════════════════
%% COL 2 ROW C: The <5% Visual Callout
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt, colback=primary,
  left=14pt, right=12pt, top=10pt, bottom=10pt,
  valign=center, drop shadow={opacity=0.22}
]{name=anchor, column=2, between=row18 and bottom}{
  \centering
  {\fontsize{100}{116}\selectfont\bfseries\color{accent} {<}5\%}\\[4pt]
  {\fontsize{34}{42}\selectfont\color{white} of published AI models reach}\\[2pt]
  {\fontsize{34}{42}\selectfont\color{white} \textbf{prospective clinical validation}}\\[8pt]
  {\fontsize{26}{34}\selectfont\color{white!70} The central challenge of AI in medicine}
}

%% ══════════════════════════════════════════════
%% COL 3 ROW A: AI vs Clinician Visual
%% ══════════════════════════════════════════════
\posterbox[tealcard, title={AI vs.\ Clinician: Head-to-Head}
]{name=comparison, column=3, between=row7 and row12}{
  \fontsize{30}{40}\selectfont

  {\fontsize{29}{36}\selectfont\color{textgray} Median diagnostic sensitivity across all imaging domains:}
  \vspace{8pt}

  \begin{center}
  \begin{tabular}{lc}
    \toprule
    & \textbf{Sensitivity} \\
    \midrule
    \rowcolor{secondary!20}
    {\fontsize{30}{38}\selectfont\bfseries\color{secondary} AI-Assisted} &
      {\fontsize{44}{52}\selectfont\bfseries\color{secondary} 87.5\%} \\[4pt]
    {\fontsize{30}{38}\selectfont\color{textdark} Clinician Only} &
      {\fontsize{44}{52}\selectfont\color{textdark} 78.2\%} \\
    \midrule
    \rowcolor{accent!15}
    {\fontsize{28}{36}\selectfont\bfseries\color{accent} Gain} &
      {\fontsize{38}{46}\selectfont\bfseries\color{accent} +9.3 pp} \\
    \bottomrule
  \end{tabular}
  \end{center}

  \vspace{8pt}
  \colorbox{secondary!22}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont\color{secondary!80!black}
    AI specificity also higher: \textbf{93.1\%} vs.\ \textbf{91.4\%} --- narrower margin but consistent
  }}

  \vspace{6pt}
  {\fontsize{27}{36}\selectfont\color{textgray}
  Gains largest in ophthalmology (+7.8 pp sensitivity), smallest in pathology (+9.9 pp spec. margin)}
}

%% ══════════════════════════════════════════════
%% COL 3 ROW B: Recommendations
%% ══════════════════════════════════════════════
\posterbox[navycard, title={Recommendations \& Future Directions}
]{name=recommendations, column=3, between=row12 and row17}{
  \fontsize{30}{40}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item \textbf{Mandate prospective validation} --- multi-site, diverse-population trials before deployment
    \item \textbf{Standardise bias auditing} --- demographic-stratified performance as a publication requirement
    \item \textbf{Safety-reporting registries} --- pharmacovigilance-style frameworks for AI-CDSS
    \item \textbf{Invest in interoperability} --- FHIR \& OMOP adoption for data infrastructure
    \item \textbf{Explainability research} --- build clinician \& patient trust in AI-augmented care
  \end{enumerate}

  \vspace{8pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont\color{primary}
    \textbf{Coordinated action} across research, regulation, and healthcare delivery is essential to close the gap
  }}
}

%% ══════════════════════════════════════════════
%% COL 3 ROW C: Key Takeaways
%% ══════════════════════════════════════════════
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row17 and bottom}{
  \fontsize{31}{42}\selectfont

  \colorbox{white!30}{\parbox{0.94\linewidth}{%
    \fontsize{30}{40}\selectfont\color{primary}
    \textbf{1.} AI improves diagnostic sensitivity by \textbf{+9.3 pp} median --- real and consistent
  }}

  \vspace{6pt}
  \colorbox{accent!30}{\parbox{0.94\linewidth}{%
    \fontsize{30}{40}\selectfont\color{accent!80!black}
    \textbf{2.} The {<}5\% validation rate is the defining crisis of AI in medicine today
  }}

  \vspace{6pt}
  \colorbox{secondary!25}{\parbox{0.94\linewidth}{%
    \fontsize{30}{40}\selectfont\color{secondary!80!black}
    \textbf{3.} Only 18\% bias assessment --- equity is a safety issue, not an afterthought
  }}

  \vspace{8pt}
  {\fontsize{26}{34}\selectfont\color{white!80}
  \textit{The Lancet Digital Health} \textbullet\ Evidence Synthesis 2023 \textbullet\ 400+ studies reviewed}
}

\end{tcbposter}
\end{document}

